    /**
     * Tests getting all InvestmentAccounts.
     *
     * @return    Collection
     */
    public List<InvestmentAccount> testGetAll() throws Throwable {
    LOGGER.info( "InvestmentAccountTest:testGetAll() - Retrieving Collection of InvestmentAccounts:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all InvestmentAccount : " );
    List<InvestmentAccount> collection  = null;

    try {
        // call the static get method on the InvestmentAccountService
        collection = service.getAllInvestmentAccount();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            InvestmentAccount currEntity  = null;
            Iterator<InvestmentAccount> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getInvestmentAccountId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

